#!/usr/bin/env python3
"""CareStream content quality gate. Usage: lint.py [files or folders]. No dependencies.
Checks house style, collection/blog structure, keyword counts, links and readability (Hemingway style flags)."""
import re, sys, os, json, urllib.request, glob

BANNED = ['crafted','solution','solutions','leverage','utilise','utilize','seamless','effortless','cutting edge','cutting-edge',
 'revolutionary','game changing','game-changing','instant','instantly','immediate','immediately','guarantee','guaranteed',
 'cqc compliant','cqc approved','cheap','cheapest','lowest price','bargain','clearance','limited time','limited stock',
 'act now','hurry','flash sale','delve','navigate the complexities','ever evolving','ever-evolving','unlock',
 "in today's fast paced world","in today's fast-paced world",'it is important to note']
AMERICAN = ['organize','organization','organizations','color','center','centers','program ','behavior','license ','analyze','prioritize','recognize','minimize','customize','favor','labor','honor','neighbor','fiber','traveling','catalog ']
SITEMAP = None

def planned():
    out = set()
    for f in glob.glob(os.path.expanduser('~/carestream-content/pilot/**/*.md'), recursive=True):
        try:
            m = re.search(r'^slug:\s*(\S+)', open(f, encoding='utf-8').read(), re.M)
            if m: out.add(m.group(1).rstrip('/'))
        except Exception: pass
    return out

def sitemap():
    global SITEMAP
    if SITEMAP is None:
        try:
            xml = urllib.request.urlopen(urllib.request.Request('https://www.carestreamai.com/sitemap.xml', headers={'User-Agent':'Mozilla/5.0'}), timeout=30).read().decode()
            SITEMAP = set(re.findall(r'<loc>https?://[^/]+([^<]*)</loc>', xml))
            SITEMAP = {u.rstrip('/') or '/' for u in SITEMAP}
        except Exception as e:
            SITEMAP = set()
    return SITEMAP

def parse_front(text):
    m = re.match(r'^---\n(.*?)\n---\n(.*)$', text, re.S)
    if not m: return None, text
    fm, body = m.group(1), m.group(2)
    d = {}
    key = None
    for line in fm.split('\n'):
        mm = re.match(r'^([a-z_]+):\s*(.*)$', line)
        if mm:
            key = mm.group(1); d[key] = mm.group(2).strip()
        elif key and line.strip():
            d[key] = (d[key] + '\n' + line).strip()
    return d, body

def words(t): return re.findall(r"[A-Za-z0-9£'’%.-]+", t)
def wc(t): return len(re.findall(r"\b[\w'’£%-]+\b", t))
def syll(w):
    w = w.lower(); w = re.sub(r'[^a-z]', '', w)
    if not w: return 0
    n = len(re.findall(r'[aeiouy]+', w))
    if w.endswith('e') and n > 1: n -= 1
    return max(n, 1)

def strip_md(t):
    t = re.sub(r'`[^`]*`', ' ', t)
    t = re.sub(r'\[([^\]]+)\]\([^)]+\)', r'\1', t)
    t = re.sub(r'^\s*[#>*\-\d.]+\s+', '', t, flags=re.M)
    return t

def sections(body):
    """split into (level, heading, text) blocks"""
    parts = re.split(r'^(#{1,4})\s+(.*)$', body, flags=re.M)
    out = [(0, '', parts[0])]
    for i in range(1, len(parts), 3):
        out.append((len(parts[i]), parts[i+1].strip(), parts[i+2]))
    return out

def lint(path):
    issues, warns, info = [], [], []
    text = open(path, encoding='utf-8').read()
    fm, body = parse_front(text)
    # :::note ... ::: callouts (light blue box for invented scenarios and disclaimers)
    _raw_outside = re.sub(r'!\[[^\]]*\]\([^)]*\)', '', re.sub(r':::note\n.*?\n:::', '', body, flags=re.S))
    if re.search(r'\b(is invented|are invented|made up|fictional|an illustration|are illustrations?|nothing below happened)\b', _raw_outside, re.I):
        _scenario_unboxed = True
    else:
        _scenario_unboxed = False
    body = re.sub(r'^:::.*$', '', body, flags=re.M)
    if fm is None:
        return ['no front matter'], [], []
    ptype = fm.get('type', '')
    # strip the "Meta title options" tail from body counts
    meta_tail = ''
    mm = re.search(r'\n#{1,3}\s*Meta title options.*$', body, re.S | re.I)
    if mm: meta_tail = mm.group(0); body = body[:mm.start()]
    plain = strip_md(body)
    allw = wc(plain)
    info.append(f'words={allw}')

    # required front matter
    for k in ['type','family','title','slug','primary_keyword','meta_title','meta_description']:
        if not fm.get(k): issues.append(f'front matter missing: {k}')
    mt = fm.get('meta_title','')
    if mt and (len(mt) >= 70 or not mt.rstrip().endswith('| CareStream')): issues.append(f'meta_title must be under 70 chars and end "| CareStream" ({len(mt)})')
    md = fm.get('meta_description','')
    if md and not (130 <= len(md) <= 160): warns.append(f'meta_description length {len(md)} (aim 140 to 155)')

    # language rules
    if re.search(r'[–—]', text): issues.append('em or en dash found')
    if re.search(r'\s-\s', plain): issues.append('space hyphen space (hyphen used as dash)')
    if re.search(r'\*\*[^*]+\*\*|__[^_]+__', body): issues.append('bold text in body')
    if re.search(r'(?<![*\w])\*[^*\s][^*\n]*[^*\s]\*(?!\w)', re.sub(r'^\s*\*\s', '', body, flags=re.M)): warns.append('possible italic text in body')
    low = plain.lower()
    for b in BANNED:
        n = len(re.findall(r'(?<![a-z])' + re.escape(b) + r'(?![a-z])', low))
        if n: issues.append(f'banned word "{b}" x{n}')
    for a in AMERICAN:
        if re.search(r'(?<![a-z])' + re.escape(a), low): warns.append(f'possible American spelling "{a.strip()}"')
    if re.search(r'click here', low): issues.append('"click here" anchor')
    if re.search(r'(?<![A-Za-z])I(?![A-Za-z.\'’])\s', plain) and ' I ' in plain: warns.append('first person "I" found')

    # No unverified claims are allowed to reach publication
    nchk = len(re.findall(r'\[CHECK', body))
    if nchk: issues.append(f'{nchk} [CHECK] markers: verify against a primary source, reword as clearly our own view, or cut the claim')
    unv = fm.get('unverified', '').strip().strip('[]').strip()
    if unv: issues.append('front matter "unverified" must be empty at publication')
    if not re.match(r'\d{4}-\d{2}-\d{2}$', fm.get('facts_verified', '').strip()):
        issues.append('front matter facts_verified: YYYY-MM-DD missing (date every factual claim was checked against its source)')

    # secondary keyword coverage for blog posts: every one must appear in the body
    if fm.get('type', '') == 'blog' or fm.get('family', '') == 'blog':
        pass
    _sec = [x.strip().strip('"\' ').lower() for x in re.split(r',|\n', fm.get('secondary_keywords','').strip('[]')) if x.strip()]
    _rel = [x.strip().strip('"\' ').lower() for x in re.split(r',|\n', fm.get('related_keywords','').strip('[]')) if x.strip()]
    if fm.get('type','') != 'collection':
        for k in _sec:
            if low.count(k) < 1: issues.append(f'secondary keyword "{k}" does not appear in the body')
        for k in _rel:
            if low.count(k) < 1: warns.append(f'related keyword "{k}" does not appear in the body')
        if len(_sec) < 4: warns.append(f'only {len(_sec)} secondary keywords (aim for 4 to 8 from Search Console and Keyword Planner)')
        _pk = fm.get('primary_keyword','').strip().lower()
        if _pk and _pk not in ' '.join(low.split()[:120]): warns.append('primary keyword not in the first 120 words')

    # internal links exist
    sm = sitemap()
    links = re.findall(r'(?<!!)\[[^\]]*\]\((https?://www\.carestreamai\.com[^)\s]*|/[^)\s]*)\)', body)
    internal = []
    for u in links:
        p = re.sub(r'^https?://www\.carestreamai\.com', '', u).split('#')[0].split('?')[0].rstrip('/') or '/'
        internal.append(p)
        if sm and p not in sm and p not in planned(): warns.append(f'internal link not in sitemap or pilot set: {p}')
    # blog/api pages exist but are in sitemap normally; keep as warning only
    if len(set(internal)) < 2: warns.append(f'fewer than 2 internal links ({len(set(internal))})')
    if re.search(r'\[[^\]]+\]\([^)]+\)', body) is None: warns.append('no links at all')

    # brand count (body)
    brand = len(re.findall(r'CareStream', plain))
    info.append(f'CareStream x{brand}')
    h1s = [s for s in sections(body) if s[0] == 1]
    h2s = [s for s in sections(body) if s[0] == 2]
    h3s = [s for s in sections(body) if s[0] == 3]
    if len(h1s) != 1: issues.append(f'need exactly one H1 (found {len(h1s)})')
    pk = fm.get('primary_keyword','').lower()
    if h1s and pk and pk not in h1s[0][1].lower():
        if ptype == 'collection': issues.append('H1 does not contain primary keyword')
        elif not all(w in h1s[0][1].lower() for w in pk.split()): warns.append('H1 does not contain all words of the primary keyword')
    info.append(f'H2={len(h2s)} H3={len(h3s)}')

    tkc = low.count(pk) if pk else 0
    info.append(f'primary "{pk}" x{tkc}')

    if ptype == 'collection':
        if '{product-grid}' not in body: issues.append('missing {product-grid} line')
        # intro: text before first H2 excluding H1 and grid
        pre = body.split('\n## ')[0]
        pre_t = strip_md(re.sub(r'^#\s.*$', '', pre, flags=re.M).replace('{product-grid}', ''))
        iw = wc(pre_t); info.append(f'intro={iw}w')
        if not (150 <= iw <= 200): issues.append(f'intro must be 150 to 200 words ({iw})')
        il = pre_t.lower()
        if pk:
            c = il.count(pk)
            if c != 2: issues.append(f'primary keyword must appear exactly twice in intro ({c})')
            first = il.find(pk)
            if first >= 0 and wc(il[:first]) >= 25: issues.append('primary keyword not within first 25 words')
            idxs = [m.start() for m in re.finditer(re.escape(pk), il)]
            if len(idxs) >= 2 and wc(il[:idxs[1]]) >= 50: issues.append('second primary keyword use not within first 50 words')
        if not (3 <= tkc <= 4 + 0): warns.append(f'primary keyword total {tkc} (rule: 3 to 4, H1 counts)')
        if brand != 3: issues.append(f'CareStream must appear exactly 3 times in body ({brand})')
        if len(h2s) < 2: issues.append('need at least 2 H2')
        if len(h3s) < 4: issues.append('need at least 4 H3')
        for lvl, h, t in sections(body):
            if lvl == 3 and wc(strip_md(t)) < 100: issues.append(f'H3 under 100 words: "{h[:50]}" ({wc(strip_md(t))})')
        sec = [s.strip().strip('[]') for s in re.split(r',|\n', fm.get('secondary_keywords','').strip('[]')) if s.strip()]
        for s in sec:
            s = s.lower().strip('"\' ')
            n = low.count(s)
            if n != 1: warns.append(f'secondary keyword "{s}" appears {n} times (rule: once)')
        if not any(re.search(r'free|get started|sign up|no card|no contract|upgrade|compare|value|available|included', h, re.I) for _, h, _ in h2s + h3s): issues.append('no commercial word in any H2/H3')
        if not any(re.search(r'who|perfect for|suits|for whom', h, re.I) for _, h, _ in h3s): warns.append('no "who it is for" H3 detected')
        n_mt = len(re.findall(r'^\s*(?:\d+[.)]|-)\s+.*\| CareStream\s*$', meta_tail, re.M))
        if n_mt < 10: issues.append(f'need 10 meta titles under the file ("Meta title options"): found {n_mt}')
        for t in re.findall(r'^\s*(?:\d+[.)]|-)\s+(.*\| CareStream)\s*$', meta_tail, re.M):
            if len(t) >= 70: issues.append(f'meta title option too long ({len(t)}): {t[:40]}')
        nf = len(re.findall(r'\n\s*-\s*q:', '\n' + fm.get('faqs','')))
        if nf < 15: issues.append(f'need 15 FAQs ({nf})')
        if not fm.get('slug','').startswith('/collection/'): issues.append('slug must begin /collection/')
    elif ptype in ('blog', 'audit-page'):
        lo, hi = (1000, 2300) if ptype == 'audit-page' else (1300, 1900)
        if not (lo <= allw <= hi): warns.append(f'word count {allw} outside {lo} to {hi}')
        if not re.search(r'^##\s+.*(conclusion|next step|what to do|where to start|summary|choose)', body, re.I | re.M): warns.append('no obvious conclusion heading')
        if not (3 <= brand <= 6): warns.append(f'CareStream appears {brand} times (aim 3 to 5)')
        nf = len(re.findall(r'\n\s*-\s*q:', '\n' + fm.get('faqs','')))
        if nf < 5: warns.append(f'fewer than 5 FAQs ({nf})')
        if ptype == 'blog' and not fm.get('slug','').startswith('/blog/'): issues.append('slug must begin /blog/')
        nsrc = len(re.findall(r'url:', fm.get('sources','')))
        if nsrc < 2: warns.append(f'fewer than 2 authoritative sources ({nsrc})')



    # evergreen rules: no dates, no time relative words, no raw prices, valid tokens, review metadata
    MONTHS = r'January|February|March|April|May|June|July|August|September|October|November|December'
    fm_scan = ' '.join(fm.get(k, '') for k in ['title','meta_title','meta_description','slug','excerpt','feature_image_alt','faqs'])
    img_alts = ' '.join(a for a, _ in re.findall(r'!\[([^\]]*)\]\(([^)\s]+)\)', body))
    scan = body + '\n' + fm_scan + '\n' + meta_tail
    scan_nolink = re.sub(r'\]\([^)]*\)', ']', scan)
    if re.search(r'\b(?:' + MONTHS + r')\s+(?:\d{4}|\d{1,2}(?:st|nd|rd|th)?\b)|\b\d{1,2}(?:st|nd|rd|th)?\s+(?:' + MONTHS + r')\b', scan_nolink):
        issues.append('calendar date found (month with day or year); remove it')
    stat = re.compile(r'(?:Act|Regulations|Code|Order|Rules|Framework|Standards)\s+(?:of\s+)?\d{4}|\b\d{4}\s+(?:Regulations|Act|Code|Order|Rules)\b|\(\d{4}\)')
    ys = stat.sub('', scan_nolink)
    allowed_upd = len(re.findall(r'\b20\d\d update\b', ys, re.I))
    ys = re.sub(r'\b20\d\d update\b', '', ys, flags=re.I)
    yrs = re.findall(r'\b20[1-3]\d\b', ys)
    if yrs: issues.append(f'year(s) in content {sorted(set(yrs))}: remove (allowed only in law names and "the 2025 update", max 2)')
    if allowed_upd > 2: warns.append(f'"20xx update" used {allowed_upd} times (max 2)')
    rel = re.findall(r'(?<![a-z])(currently|recently|latest|this year|next year|last year|at the time of writing|as of|nowadays|newly)(?![a-z])', scan_nolink.lower())
    if rel: issues.append('time relative words: ' + ', '.join(sorted(set(rel))))
    # raw prices
    pr = re.findall(r'£\s?\d[\d,]*(?:\.\d+)?', scan_nolink)
    if pr: issues.append(f'raw price(s) {sorted(set(pr))}: use a {{{{price:...}}}} token (CareStream) or remove (competitors)')
    # tokens
    try:
        import json as _j
        facts = _j.load(open(os.path.expanduser('~/carestream-content/guidelines/product-facts.json')))
    except Exception:
        facts = {}
    for tok in set(re.findall(r'\{\{([^}]+)\}\}', scan)):
        if tok.strip() not in facts: issues.append(f'unknown token {{{{{tok}}}}} (add to product-facts.json)')
    for k in ('last_reviewed', 'review_by'):
        v = fm.get(k, '').strip()
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', v): issues.append(f'front matter {k} must be YYYY-MM-DD')


    # opening checks (library: library/openings.json)
    try:
        import json as _j2
        lib = _j2.load(open(os.path.expanduser('~/carestream-content/library/openings.json')))
        ids = {m['id'] for m in lib['moves']}
    except Exception:
        ids = set()
    ot = fm.get('opening_type', '').strip()
    if ptype in ('blog', 'audit-page', 'collection'):
        if not ot: issues.append('front matter opening_type missing (see library/openings.json)')
        elif ids and ot not in ids: issues.append(f'unknown opening_type "{ot}"')
        h1stripped = re.sub(r'^#\s.*$', '', body, count=1, flags=re.M).strip()
        paras0 = [p for p in re.split(r'\n\s*\n', h1stripped) if len(p.split()) > 6 and not p.lstrip().startswith(('-', '!', '#', '|', '{', '*'))]
        if paras0:
            op = paras0[0]; ow = len(op.split())
            if ow > 95: issues.append(f'opening paragraph {ow} words (aim 60 or fewer, hard limit 95)')
            elif ow > 70: warns.append(f'opening paragraph {ow} words (aim 60 or fewer)')
            s1 = re.split(r'(?<=[.!?])\s+', op)[0]
            if len(s1.split()) > 28: issues.append(f'first sentence {len(s1.split())} words (max 28, aim 25)')
            if '[CHECK]' in ' '.join(h1stripped.split()[:110]): issues.append('[CHECK] marker in the first 100 words: do not open on an unverified claim')
            if re.search(r'\b(Standard|Regulation|Criterion|Section)\s+\d+', ' '.join(op.split()[:45])) and ptype != 'audit-page': warns.append('opening uses numbered shorthand (Standard N / Regulation N) before explaining it')

    # openings and templating (blogs and audit pages; collections have a fixed shape)
    BAD_OPENERS = ['this guide','in this guide','this article','this post','this page explains','if you have searched','if you are looking for','if you are','sooner or later','whether you','the honest answer','in this article','we will cover','let us look','you need to']
    if ptype in ('blog', 'audit-page'):
        after_h1 = re.sub(r'^#\s.*$', '', body, count=1, flags=re.M).strip()
        first150 = ' '.join(re.findall(r"\S+", strip_md(after_h1))[:150]).lower()
        for o in BAD_OPENERS:
            if o in first150: issues.append(f'banned opener/phrase in first 150 words: "{o}"')
        first120 = ' '.join(re.findall(r"\S+", strip_md(after_h1))[:120]).lower()
        if pk and pk not in first120: warns.append('primary keyword not in the first 120 words')
        for sig in ['our recommendation, not a rule', 'the honest answer', 'in practice,']:
            if low.count(sig) > 1: warns.append(f'signature phrase repeated: "{sig}"')
    # images
    imgs = re.findall(r'!\[([^\]]*)\]\(([^)\s]+)\)', body)
    fi = fm.get('feature_image', '').strip(); fia = fm.get('feature_image_alt', '').strip()
    if not fi: issues.append('missing feature_image')
    if not fia: issues.append('missing feature_image_alt')
    # BLOG HERO RULE: the feature image (hero) of a blog is always freshly generated for that post with
    # POST /routine/content/image (house style, open friendly faces). Library, stock, course and policy
    # illustrations are never used as a blog hero; they are fine inline. Generated images are served from
    # api.carestreamai.com/public/policy-shop/image/<uuid>.webp.
    if ptype == 'blog' and fi and not re.match(r'^https://api\.carestreamai\.com/public/policy-shop/image/[0-9a-f-]{36}\.webp$', fi):
        issues.append('blog hero (feature_image) must be a newly generated image from POST /routine/content/image, not a stock or library image: ' + fi[:70])
    alts = [fia] + [a for a, _ in imgs]
    for a in alts:
        if not a: continue
        if re.match(r'^(image|picture|photo|screenshot|graphic)\s+of\b', a.strip(), re.I): issues.append(f'alt text starts with "image of" style: {a[:40]}')
        if re.search(r'[–—]', a): issues.append('dash in alt text')
        if not (60 <= len(a) <= 140): warns.append(f'alt text length {len(a)} (aim 70 to 125): {a[:50]}')
    for a, u in imgs:
        if not a.strip(): issues.append(f'inline image with empty alt: {u[:50]}')
    need = {'collection': (1, 2), 'blog': (1, 4), 'audit-page': (2, 4)}.get(ptype, (1, 4))
    if not (need[0] <= len(imgs) <= need[1]): warns.append(f'{len(imgs)} inline images (aim {need[0]} to {need[1]})')
    # the feature image is the hero: it must never be repeated as an image inside the body (it looks like a mistake)
    # INLINE STYLE RULE: stock, course, policy-hero and regulation illustrations are the old image style and are banned inline.
    for _a, u in imgs:
        if re.search(r'/public/training/image/|/images/policy-law/|/images/care-policies/[a-z0-9-]+/\d+\.webp', u):
            issues.append('old style inline image (stock, course, policy or regulation illustration): generate a new one in the house style: ' + u[-50:])
    if fi and any(u.strip() == fi for _, u in imgs): issues.append('feature image is repeated as an inline image in the body: use a different image for the first inline slot')
    if '![' in meta_tail: pass
    info.append(f'images={len(imgs)}+feature')

    # readability (Hemingway style flags)
    sents = [s for s in re.split(r'(?<=[.!?])\s+', re.sub(r'\n+', ' ', plain)) if len(s.split()) > 2]
    if sents:
        lens = [len(s.split()) for s in sents]
        avg = sum(lens) / len(lens)
        longs = sum(1 for l in lens if l > 30)
        ws = [w for w in re.findall(r"[A-Za-z']+", plain)]
        sy = sum(syll(w) for w in ws)
        fre = 206.835 - 1.015 * avg - 84.6 * (sy / max(len(ws), 1))
        fk = 0.39 * avg + 11.8 * (sy / max(len(ws), 1)) - 15.59
        adv = sum(1 for w in ws if w.lower().endswith('ly') and w.lower() not in ('only','family','early','daily','weekly','monthly','yearly','quarterly','annually','supply','apply','reply','assembly','italy','july','likely','friendly','ally','rely','multiply','anomaly'))
        pas = len(re.findall(r'\b(?:is|are|was|were|be|been|being)\s+(?:\w+ly\s+)?\w+ed\b', plain.lower()))
        info.append(f'avg sentence {avg:.1f}w, FK grade {fk:.1f}, Flesch {fre:.0f}, long sentences(>30w) {longs}, adverbs/100w {adv*100/max(len(ws),1):.1f}, passive/100 sentences {pas*100/len(sents):.0f}')
        import statistics as _st
        sd = _st.pstdev(lens) if len(lens) > 5 else 0
        info.append(f'sentence length spread (sd) {sd:.1f}')
        if len(lens) > 20 and sd < 6.5: warns.append(f'sentence length too uniform (spread {sd:.1f}; vary it: aim for 7 or more)')
        if avg > 22: warns.append(f'average sentence length {avg:.1f} words (aim under 20)')
        if longs > 4: warns.append(f'{longs} sentences over 30 words')
        if fk > 11: warns.append(f'reading grade {fk:.1f} (aim 8 to 10 for practitioners)')
        if adv * 100 / max(len(ws), 1) > 1.5: warns.append('many adverbs (-ly words)')
        if pas * 100 / len(sents) > 18: warns.append('high passive voice rate')

    # ---- paragraph, sentence and link discipline (hard rules) ----
    _body = re.sub(r'<!--.*?-->', '', body, flags=re.S)
    _body = re.sub(r'```.*?```', '', _body, flags=re.S)
    _paras = []
    for blk in re.split(r'\n\s*\n', _body):
        b = blk.strip()
        if not b or b.startswith(('#', '|', '!', '<', '{', '>', '-', '*')) or re.match(r'\d+[.)]\s', b): continue
        if b.lower().startswith(('figure:', 'source:')): continue
        _paras.append(b)
    def _sents(t):
        t = re.sub(r'\[([^\]]+)\]\([^)]*\)', r'\1', t)
        t = re.sub(r'\b(e\.g|i\.e|etc|vs|no|approx)\.', r'\1', t)
        return [x for x in re.split(r'(?<=[.!?])\s+', t) if len(x.split()) > 1]
    LEGAL_FULL = re.compile(r'Regulations? \d+[\w()]*\s+of\s+the\s+')
    INSTR = re.compile(r'(?:[A-Z][A-Za-z]+ )+(?:\(Regulated Activities\) )?(?:Act|Regulations) \d{4}|Regulation \d+[\w()]*|Code of [Pp]ractice|statutory guidance')
    bad_p = bad_s = bad_l = bad_g = 0
    for pa in _paras:
        ss = _sents(pa); n = len(pa.split())
        if n > 70: issues.append(f'paragraph {n} words (max 70, aim 40 to 55): "{pa[:50]}..."'); bad_p += 1
        elif len(ss) > 4 or (len(ss) == 4 and n >= 60): issues.append(f'paragraph has {len(ss)} sentences in {n} words (max 3, or 4 under 60 words): "{pa[:50]}..."'); bad_p += 1
        for sn in ss:
            wl = len(sn.split())
            if wl > 28: issues.append(f'sentence {wl} words (max 28): "{sn[:60]}..."'); bad_s += 1
            refs = INSTR.findall(LEGAL_FULL.sub('', re.sub(r'\s+', ' ', sn)))
            refs = [r for r in refs if not re.fullmatch(r'Regulation \d+[\w()]*', r) or True]
            if len(refs) > 1: issues.append(f'sentence cites {len(refs)} legal references (max 1; split it or use a list): "{sn[:60]}..."'); bad_l += 1
        fkp = 0.39 * (n / max(len(ss), 1)) + 11.8 * (sum(syll(w) for w in re.findall(r"[A-Za-z']+", pa)) / max(len(re.findall(r"[A-Za-z']+", pa)), 1)) - 15.59
        if n > 25 and fkp > 11: issues.append(f'paragraph reading grade {fkp:.1f} (max 11): "{pa[:50]}..."'); bad_g += 1
    if sents and fk > 9: issues.append(f'page reading grade {fk:.1f} (max 9)')
    # external links
    AUTH = ('legislation.gov.uk', 'gov.uk', 'cqc.org.uk', 'skillsforcare.org.uk', 'skillsforhealth.org.uk', 'england.nhs.uk', 'nhs.uk', 'nhsemployers.org', 'hse.gov.uk', 'food.gov.uk', 'ico.org.uk', 'scie.org.uk', 'ofsted.gov.uk', 'ofqual.gov.uk')
    GENERIC = re.compile(r'^(here|this|link|source|website|read more|click|page|more|this page|this link|see more|official site)$', re.I)
    for blk in re.split(r'\n\s*\n', _body):
        ext = re.findall(r'(?<!!)\[([^\]]*)\]\((https?://[^)\s]+)\)', blk)
        ext = [(a, u) for a, u in ext if 'carestreamai.com' not in u]
        if len(ext) > 1: issues.append(f'{len(ext)} external links in one paragraph (max 1): "{blk.strip()[:50]}..."')
        if ext and blk.strip().startswith('#'): issues.append('external link inside a heading')
        for a, u in ext:
            host = re.sub(r'^https?://(www\.)?', '', u).split('/')[0]
            if len(a.split()) < 3: issues.append(f'external anchor "{a}" too short: name what the reader gets (3 or more words)')
            if GENERIC.match(a.strip()) or re.search(r'\b[a-z0-9-]+\.(?:gov\.uk|co\.uk|org\.uk|com|org|uk)\b', a, re.I): issues.append(f'external anchor "{a}" is a domain or generic word: describe the page, e.g. "full text of Regulation 12"')
            if not any(host == d or host.endswith('.' + d) for d in AUTH): issues.append(f'external link to non authority domain {host} (allowed: primary sources only)')
    if _scenario_unboxed: issues.append('invented scenario or illustration disclaimer must sit in a :::note callout (light blue box), not in body text')
    # vague references to a source: name the document
    VAGUE = re.compile(r"(?<!' )\b(?:the )?(?:official )?(?:FAQ|FAQs|guidance|document|report|framework|paper|standards document)\b(?= (?:says|states|calls|names|lists|explains|confirms|notes)\b)", re.I)
    for _pa in _paras:
        for _m in VAGUE.finditer(_pa):
            issues.append(f'vague source "{_m.group(0)}": name the document (its title and publisher) on first mention and give it a short name: "{_pa[max(0,_m.start()-30):_m.end()+20]}"')
    # ---- collection pages: the copy below the product grid must carry real links and a clean heading outline (Len, 18 Nov 2026) ----
    if ptype == 'collection':
        _below = body.split('{product-grid}', 1)[1] if '{product-grid}' in body else body
        _lk = re.findall(r'(?<!!)\[([^\]]*)\]\((https?://[^)\s]+|/[^)\s]+)\)', _below)
        _int = [(a, u) for a, u in _lk if u.startswith('/') or 'carestreamai.com' in u]
        _ext = [(a, u) for a, u in _lk if not (u.startswith('/') or 'carestreamai.com' in u)]
        if len({re.sub(r'^https?://www\.carestreamai\.com', '', u).split('#')[0].split('?')[0].rstrip('/') for _, u in _int}) < 3:
            issues.append('collection needs at least 3 different internal links in the copy below the product grid (sitemap URLs, descriptive anchors)')
        if len({u for _, u in _ext}) < 2:
            issues.append('collection needs at least 2 different external links to primary sources in the copy below the product grid (legislation.gov.uk, gov.uk, cqc.org.uk, nice.org.uk, hse.gov.uk, skillsforcare.org.uk and the like)')
        _bad_int = [a for a, u in _int if len(a.split()) < 2 or re.match(r'^(here|this|link|read more|click here|more|see more|learn more|find out more|page)$', a.strip(), re.I)]
        if _bad_int: issues.append(f'internal anchor too short or generic: "{_bad_int[0]}" (use 2 or more descriptive words, ideally a long tail phrase that say what the reader gets)')
        # headings: every section below the grid is a real H2 or H3, starting with an H2, never skipping a level
        _hs = [(len(m.group(1)), m.group(2).strip()) for m in re.finditer(r'^(#{1,6})\s+(.+)$', _below, re.M)]
        if not _hs or _hs[0][0] != 2: issues.append('the first heading below the product grid must be an H2')
        _prev = 1
        for lvl, txt in _hs:
            if lvl == 1: issues.append(f'H1 inside the body: "{txt[:40]}"')
            elif lvl > 3: issues.append(f'H{lvl} used: only H2 and H3 are allowed below the grid ("{txt[:40]}")')
            elif lvl > _prev + 1: issues.append(f'heading level skipped before "{txt[:40]}" (H{_prev} to H{lvl})')
            _prev = lvl
        if sum(1 for l, _ in _hs if l == 2) < 2: issues.append('at least two H2 headings are needed below the product grid')
        if sum(1 for l, _ in _hs if l == 3) < 4: issues.append('at least four H3 headings are needed below the product grid')
        for _m in re.finditer(r'^(?:\*\*[^*\n]{3,90}\*\*|[A-Z][^.\n]{3,70}:)\s*$', _below, re.M):
            issues.append(f'a line that looks like a heading but is not one: "{_m.group(0)[:40]}" (make it an H2 or H3)')
    info.append(f'paras={len(_paras)} bad_para={bad_p} bad_sent={bad_s} bad_legal={bad_l}')
    # URL rule: slug is the slugified primary keyword (one owner URL per keyword), unless an exception is recorded
    _slug = re.sub(r'^/?(blog|collection|audits)/', '', fm.get('slug', '').strip())
    _pkw = re.sub(r'[^a-z0-9]+', '-', fm.get('primary_keyword', '').lower()).strip('-')
    if _slug and _pkw and _slug != _pkw and not fm.get('slug_exception', '').strip():
        issues.append(f'slug "{_slug}" must equal the slugified primary keyword "{_pkw}" (or record slug_exception: reason)')
    if len(_slug) > 60: issues.append(f'slug {len(_slug)} characters (max 60)')
    if re.search(r'-(explained|guide|uk|2\d{3})$', _slug) and not fm.get('slug_exception', '').strip(): issues.append('slug has a filler suffix (-explained, -guide, -uk, year)')
    # calls to action: the template weaves the cta_type block into the article twice and ends with a button
    if fm.get('type', '') == 'blog':
        if fm.get('cta_type', '').strip() not in ('free_cpd_course', 'free_audits', 'free_policy_check', 'book_demo', 'discuss_training'):
            issues.append('blog needs cta_type: free_cpd_course | free_audits | free_policy_check (woven into the post twice; the end button is added by the converter)')
        _prod = re.findall(r'\]\((?:https://www\.carestreamai\.com)?/(?:staff-training|care-audits|policy-gap-detection|care-policies|features|register|pricing)[^)]*\)', body)
        if not _prod: issues.append('blog needs at least one inline link to a free product page (course, audits, policy check) in the body')
    # Benefits of CareStream section: reconfirms the service with the primary keyword, before the conclusion
    if fm.get('type', '') in ('blog', 'collection'):
        _h2s = [h for lvl, h, t in sections(body) if lvl == 2]
        _ben = [i for i, h in enumerate(_h2s) if re.search(r'benefits? of (using )?carestream', h, re.I)]
        if not _ben: issues.append('missing a "Benefits of CareStream ..." H2 (reconfirms the service with the primary keyword)')
        else:
            _sec_txt = [t for lvl, h, t in sections(body) if lvl == 2 and re.search(r'benefits? of (using )?carestream', h, re.I)][0]
            _pk = fm.get('primary_keyword', '').strip().lower()
            if _pk and _pk not in (_sec_txt + ' ' + _h2s[_ben[0]]).lower(): issues.append('Benefits of CareStream section must use the primary keyword once')
            if wc(strip_md(_sec_txt)) > 170: issues.append('Benefits of CareStream section over 170 words')
            if fm.get('type', '') == 'blog' and _ben[0] < len(_h2s) - 3: warns.append('Benefits section should sit just above the conclusion or final call to action')
    # Commercial vocabulary (collections only): a small natural set of words that match what is really sold
    if fm.get('type', '') == 'collection':
        try:
            _cv = json.load(open(os.path.expanduser('~/carestream-content/guidelines/commercial-terms.json')))
        except Exception:
            _cv = None
        if _cv:
            _txt = ' ' + re.sub(r'[^a-z0-9 \-]+', ' ', body.lower()) + ' '
            _have = [w for w in _cv['count_as_commercial'] if re.search(r'(?<![a-z])' + re.escape(w) + r'(?![a-z])', _txt)]
            if len(_have) < _cv['min_distinct']: issues.append(f'collection needs at least {_cv["min_distinct"]} commercial words that match what is sold (found {len(_have)}: {_have}); see guidelines/commercial-terms.json')
            if len(_have) > _cv['max_distinct']: warns.append(f'{len(_have)} distinct commercial words (aim {_cv["min_distinct"]} to {_cv["max_distinct"]}); keep the text natural')
            _hd = ' '.join(h.lower() for _l, h, _t in sections(body) if _l in (2, 3))
            if not any(re.search(r'(?<![a-z])' + re.escape(w) + r'(?![a-z])', _hd) for w in _cv['count_as_commercial']): issues.append('no commercial word in any H2 or H3 heading')
            _bad = [w for w in _cv['forbidden'] if re.search(r'(?<![a-z])' + re.escape(w) + r'(?![a-z])' + (r'(?! with)' if w == 'deals' else ''), _txt.replace('checking in stock', 'checking stock'))]
            if _bad: issues.append(f'commercial words we cannot back up (remove): {_bad}')
    return issues, warns, info


def cross(files):
    docs = {}
    for f in files:
        if os.path.basename(f).lower() == 'readme.md': continue
        text = open(f, encoding='utf-8').read()
        fm, body = parse_front(text)
        if not fm: continue
        body = re.split(r'\n#{1,3}\s*Meta title options', body)[0]
        docs[f] = (fm, body)
    out = []
    firsts, heads, shingles = {}, {}, {}
    for f, (fm, body) in docs.items():
        paras = [p for p in re.split(r'\n\s*\n', re.sub(r'^#.*$', '', body, flags=re.M)) if len(p.split()) > 8 and not p.lstrip().startswith(('-', '*', '|', '!', '{', '1.'))]
        if paras:
            k = ' '.join(re.findall(r"[a-z']+", paras[0].lower())[:6])
            firsts.setdefault(k, []).append(f)
        for lvl, h, _ in sections(body):
            if fm.get('type') == 'collection': continue
            if lvl in (2, 3) and h: heads.setdefault(re.sub(r'[^a-z0-9 ]', '', h.lower()).strip(), []).append(f)
        ws = re.findall(r"[a-z0-9']+", strip_md(body).lower())
        shingles[f] = {' '.join(ws[i:i+8]) for i in range(0, max(len(ws) - 7, 0))}
    for k, fs in firsts.items():
        if len(fs) > 1: out.append(('ERROR', f'same first six words ("{k}") in: ' + ', '.join(os.path.basename(x) for x in fs)))
    COMMON = {'frequently asked questions', 'faqs', 'sources', 'meta title options'}
    for k, fs in heads.items():
        if len(set(fs)) > 1 and k not in COMMON: out.append(('ERROR', f'same heading "{k}" on: ' + ', '.join(sorted(os.path.basename(x) for x in set(fs)))))
    names = list(shingles)
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            a, b = shingles[names[i]], shingles[names[j]]
            if not a or not b: continue
            share = len(a & b) / min(len(a), len(b))
            if share > 0.04: out.append(('WARN', f'{share:.0%} shared 8 word phrases: {os.path.basename(names[i])} and {os.path.basename(names[j])}'))
    sa = [f for f, (fm, body) in docs.items() if re.search(r'^##\s+(short answer|the short version|quick answer)', body, re.I | re.M)]
    blogs = [f for f, (fm, b) in docs.items() if fm.get('type') in ('blog', 'audit-page')]
    if blogs and len(sa) > max(1, len(blogs) // 3): out.append(('WARN', f'"Short answer" style block on {len(sa)} of {len(blogs)} posts (keep it to a third)'))
    ends = [f for f, (fm, body) in docs.items() if re.search(r'^##\s+conclusion', body, re.I | re.M)]
    if ends: out.append(('ERROR', 'a heading called Conclusion on: ' + ', '.join(os.path.basename(x) for x in ends)))

    # near identical sentences across pages
    sent_sets = {}
    for f, (fm, body) in docs.items():
        txt = re.sub(r'^---.*?---', '', body, flags=re.S)
        txt = re.sub(r'^!\[.*$', '', txt, flags=re.M)
        txt = re.sub(r'^Figure:.*$', '', txt, flags=re.M)
        ss = [s.strip() for s in re.split(r'(?<=[.!?])\s+', re.sub(r'\n+', ' ', strip_md(txt))) if len(s.split()) >= 9]
        sent_sets[f] = [(s, frozenset(re.findall(r"[a-z0-9']+", s.lower()))) for s in ss]
    fl = list(sent_sets)
    for i in range(len(fl)):
        for j in range(i + 1, len(fl)):
            if docs[fl[i]][0].get('type') == 'collection' and docs[fl[j]][0].get('type') == 'collection': pass
            hits = []
            for s1, w1 in sent_sets[fl[i]]:
                for s2, w2 in sent_sets[fl[j]]:
                    if len(w1 & w2) / max(len(w1 | w2), 1) >= 0.7: hits.append(s1[:70]); break
            if len(hits) >= 2: out.append(('ERROR', f'{len(hits)} near identical sentences in {os.path.basename(fl[i])} and {os.path.basename(fl[j])} e.g. "{hits[0]}"'))
            elif len(hits) == 1: out.append(('WARN', f'1 near identical sentence in {os.path.basename(fl[i])} and {os.path.basename(fl[j])}: "{hits[0]}"'))
    # boilerplate phrases
    for ph in ['we flag what we could not confirm', 'prices and offers change', 'here is an example, not a real case', 'confirm on the provider', 'we compared the standards with']:
        used = [os.path.basename(f) for f, (fm, body) in docs.items() if ph in body.lower()]
        if len(used) > 1: out.append(('ERROR', f'boilerplate phrase "{ph}" on: ' + ', '.join(used)))
    # image reuse
    use = {}; feat = {}
    for f, (fm, body) in docs.items():
        urls = set(re.findall(r'!\[[^\]]*\]\(([^)\s]+)\)', body)); fi = fm.get('feature_image', '').strip()
        if fi: feat.setdefault(fi, []).append(os.path.basename(f)); urls.add(fi)
        for u in urls: use.setdefault(u, []).append(f)
    for u, fs in feat.items():
        if len(fs) > 1: out.append(('ERROR', f'feature image reused on {", ".join(fs)}: {u.split("/")[-1]}'))
    for u, fs in use.items():
        if len(fs) > 2: out.append(('ERROR', f'image on more than two pages ({len(fs)}): {u.split("/")[-1]}'))
    blogs_by_fam = {}
    for f, (fm, body) in docs.items():
        if fm.get('type') == 'blog': blogs_by_fam.setdefault(fm.get('family', ''), []).append(f)
    for fam, fs in blogs_by_fam.items():
        for i in range(len(fs)):
            for j in range(i + 1, len(fs)):
                a = {u for u, l in use.items() if fs[i] in l}; b = {u for u, l in use.items() if fs[j] in l}
                if a & b: out.append(('ERROR', f'two posts in family {fam} share an image: {os.path.basename(fs[i])}, {os.path.basename(fs[j])}: {sorted(x.split("/")[-1] for x in a & b)}'))

    ot_use = {}
    f12 = {}
    for f, (fm, body) in docs.items():
        ot = fm.get('opening_type', '').strip()
        if ot: ot_use.setdefault(ot, []).append(os.path.basename(f))
        h1 = re.sub(r'^#\s.*$', '', body, count=1, flags=re.M)
        ps = [p for p in re.split(r'\n\s*\n', h1) if len(p.split()) > 6 and not p.lstrip().startswith(('-', '!', '#', '|', '{', '*'))]
        if ps: f12.setdefault(' '.join(re.findall(r"[a-z0-9']+", ps[0].lower())[:12]), []).append(os.path.basename(f))
    for ot, fs in ot_use.items():
        if len(fs) > 1 and len(docs) < 20: out.append(('ERROR', f'opening type "{ot}" used by {len(fs)} pages: ' + ', '.join(fs)))
    for k, fs in f12.items():
        if len(fs) > 1: out.append(('ERROR', 'same first twelve words: ' + ', '.join(fs)))
    return out

def main():
    args = sys.argv[1:] or [os.path.expanduser('~/carestream-content/pilot')]
    files = []
    for a in args:
        if os.path.isdir(a): files += glob.glob(os.path.join(a, '**', '*.md'), recursive=True)
        else: files.append(a)
    total_fail = 0
    for f in sorted(files):
        if os.path.basename(f).lower() in ('readme.md',): continue
        issues, warns, info = lint(f)
        status = 'FAIL' if issues else ('WARN' if warns else 'PASS')
        if issues: total_fail += 1
        print(f'\n[{status}] {os.path.relpath(f, os.path.expanduser("~/carestream-content"))}')
        print('   ' + ' | '.join(info))
        for i in issues: print('   ERROR  ' + i)
        for w in warns: print('   warn   ' + w)
    cx = cross(files) if len(files) > 1 else []
    if cx:
        print('\n[CROSS PAGE SAMENESS CHECK]')
        for lvl, msg in cx:
            print(f'   {lvl:5} {msg}')
            if lvl == 'ERROR': total_fail += 1
    else:
        if len(files) > 1: print('\n[CROSS PAGE SAMENESS CHECK] PASS')
    print(f'\n{len(files)} files, {total_fail} with errors')
    sys.exit(1 if total_fail else 0)
if __name__ == '__main__':
    main()

