#!/usr/bin/env python3
"""Convert pilot collection pages (resolved previews) to the JSON the platform Collections 'Import drafts' accepts."""
import sys, os, re, json
sys.path.insert(0, os.path.dirname(__file__))
import to_blogpost as t
CLUSTERS = {'training': 'free-cpd-courses', 'policies': 'governance-and-cqc', 'audits': 'home-care-audits'}
EYEBROW = {'training': 'Training collection', 'policies': 'Policy collection', 'audits': 'Audit collection'}
def convert(path):
    fm, body = t.parse_front(open(path, encoding='utf-8').read())
    if fm.get('type') != 'collection': return None
    body = re.split(r'\n#{1,3}\s*Meta title options', body)[0]
    pre, _, post = body.partition('{product-grid}')
    kind = fm.get('kind') or ('training' if fm.get('family') == 'care-certificate' else 'policies')
    sec = fm.get('secondary_keywords', []); sec = sec if isinstance(sec, list) else []
    links = []
    il = fm.get('internal_links', [])
    for u in (il if isinstance(il, list) else []):
        u = u.strip(); label = u.rstrip('/').split('/')[-1].replace('-', ' ').capitalize()
        if u: links.append({'label': label, 'url': u})
    return {
        'title': fm.get('title', ''), 'slug': fm.get('slug', '').strip('/').replace('collection/', ''),
        'meta_title': fm.get('meta_title', ''), 'meta_description': fm.get('meta_description', ''),
        'kind': kind, 'cluster_key': fm.get('cluster_key') or CLUSTERS[kind], 'eyebrow': EYEBROW[kind],
        'intro': t.md_to_html(pre), 'body': t.md_to_html(post),
        'links': links, 'faqs': [{'question': q['question'], 'answer': q['answer']} for q in t.faqs_from(fm.get('faqs', []))],
        'topic_cluster': fm.get('topic_cluster', '').strip(), 'previous_slug': fm.get('previous_slug', '').strip(), 'primary_keyword': fm.get('primary_keyword', ''), 'secondary_keywords': sec, 'status': 'draft',
    }
if __name__ == '__main__':
    items = [c for c in (convert(f) for f in sys.argv[2:]) if c]
    json.dump(items, open(sys.argv[1], 'w'), indent=2, ensure_ascii=False)
    for c in items: print(c['slug'], c['kind'], c['cluster_key'], 'intro words', len(re.sub('<[^>]+>', ' ', c['intro']).split()), 'body words', len(re.sub('<[^>]+>', ' ', c['body']).split()), 'faqs', len(c['faqs']), 'kw', len(c['secondary_keywords']))

