#!/usr/bin/env python3
"""Cross page checks for a NEW page against every page already on the platform (published and draft).
Usage: nightly_check.py state.json page.md [page2.md ...]
state.json is the output of GET /routine/content/state. This is the nightly equivalent of lint.py's cross page sameness check
(that one needs every page as a markdown file; the platform only holds HTML). Exit 1 on any ERROR."""
import sys, os, re, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import lint as L

def norm(s): return re.sub(r'[^a-z0-9 ]+', '', s.lower()).strip()
def first12(s): return ' '.join(re.findall(r"[a-z0-9']+", s.lower())[:12])

def main():
    state = json.load(open(sys.argv[1]))
    pages = state['blogs'] + state['collections']
    owned_kw = {norm(p.get('primary_keyword') or ''): p['slug'] for p in pages if p.get('primary_keyword')}
    slugs = {p['slug'] for p in pages}
    heads = {}
    for p in pages:
        for h in p.get('h2s', []): heads.setdefault(norm(h), p['slug'])
    f12 = {p.get('first12'): p['slug'] for p in pages if p.get('first12')}
    feat = {}
    inline = {}
    for p in pages:
        for u in p.get('images', []): inline.setdefault(u, []).append(p['slug'])
        if p.get('feature_image'): feat[p['feature_image']] = p['slug']
    fails = 0
    for f in sys.argv[2:]:
        text = open(f, encoding='utf-8').read()
        fm, body = L.parse_front(text)
        errs, warns = [], []
        if not fm: print(f'[FAIL] {f}: no front matter'); fails += 1; continue
        slug = (fm.get('slug') or '').strip().strip('/')
        short = slug.split('/', 1)[-1]
        if short in slugs: errs.append(f'slug already on the platform: {short}')
        pk = norm(fm.get('primary_keyword', ''))
        if pk in owned_kw: errs.append(f'primary keyword "{pk}" is already owned by {owned_kw[pk]}')
        for m in re.finditer(r'^##\s+(.*)$', body, re.M):
            h = norm(m.group(1))
            if h in heads: errs.append(f'heading "{m.group(1).strip()}" is already used on {heads[h]}')
        ps = [p for p in re.split(r'\n\s*\n', re.sub(r'^#\s.*$', '', body, count=1, flags=re.M))
              if len(p.split()) > 6 and not p.lstrip().startswith(('-', '!', '#', '|', '{', '*'))]
        if ps and first12(ps[0]) in f12: errs.append(f'same first twelve words as {f12[first12(ps[0])]}')
        fi = (fm.get('feature_image') or '').strip()
        if fi and fi in feat: errs.append(f'feature image already used as the feature image of {feat[fi]}')
        for u in re.findall(r'!\[[^\]]*\]\(([^)]+)\)', body):
            if len(inline.get(u, [])) >= 2: warns.append(f'inline image already used on two pages: {u.split("/")[-1]}')
        status = 'FAIL' if errs else ('WARN' if warns else 'PASS')
        fails += 1 if errs else 0
        print(f'[{status}] {os.path.basename(f)}')
        for e in errs: print('   ERROR  ' + e)
        for w in warns: print('   warn   ' + w)
    sys.exit(1 if fails else 0)

if __name__ == '__main__':
    main()

