 "faqs": {
  "heading": "Staff supervision and CareStream, answered",
  "groups": [
   {
    "group": "About supervision records",
    "items": [
     {
      "q": "What should supervision records contain?",
      "a": "At least the date, who took part, what was discussed, what was agreed and when the next session is due. CareStream records each of these, and the completed form and agreed actions stay on the person's staff record."
     },
     {
      "q": "Is there a supervision template I can use?",
